/**
 * Catalog emission dialect for org tables (inline columns bag).
 */
import { asNamedRef, safeCatalogKey, } from "../../catalog/render-helpers.js";
export function renderTableCatalogEntry(args) {
    const named = asNamedRef(args.ref);
    const ref = args.ref;
    // A table catalog is exported directly from its per-table module, not
    // nested inside orgCatalog's `tables` bag where stampTableRefs could inject
    // the bag key. Preserve that stable authored identity explicitly; otherwise
    // tableRef falls back to the display name and downstream typed references
    // derive an invalid Terraform lookup label from it.
    const parts = [
        `refName: ${JSON.stringify(args.keyName)}`,
        `name: ${JSON.stringify(ref.name)}`,
    ];
    const extraFactories = [];
    const columns = Object.entries(ref.columns ?? {}).sort(([a], [b]) => a.localeCompare(b));
    if (columns.length > 0) {
        extraFactories.push("tableColumnRef");
        const parentHandle = named.refName ?? args.keyName;
        const rendered = columns
            .map(([key, column]) => {
            const colParts = [
                `name: ${JSON.stringify(column.name)}`,
                `parent: ${JSON.stringify(parentHandle)}`,
                `parentName: ${JSON.stringify(ref.name)}`,
            ];
            if (column.fieldType !== undefined) {
                colParts.push(`fieldType: ${JSON.stringify(column.fieldType)}`);
            }
            if (column.tags !== undefined)
                colParts.push(`tags: ${JSON.stringify(column.tags)}`);
            return `${safeCatalogKey(key)}: tableColumnRef({ ${colParts.join(", ")} })`;
        })
            .join(", ");
        parts.push(`columns: { ${rendered} }`);
    }
    const datamines = Object.entries(ref.datamines ?? {}).sort(([a], [b]) => a.localeCompare(b));
    if (datamines.length > 0) {
        extraFactories.push("datamineRef");
        const parentHandle = named.refName ?? args.keyName;
        parts.push(`datamines: { ${datamines.map(([key, datamine]) => `${safeCatalogKey(key)}: datamineRef({ name: ${JSON.stringify(datamine.name)}, parent: ${JSON.stringify(parentHandle)}, parentName: ${JSON.stringify(ref.name)} })`).join(", ")} }`);
    }
    if (ref.categoryId !== undefined) {
        parts.push(`categoryId: ${JSON.stringify(ref.categoryId)}`);
    }
    return {
        lines: [
            `${args.baseIndent}${safeCatalogKey(args.keyName)}: tableRef({ ${parts.join(", ")} }),`,
        ],
        extraFactories: extraFactories.length > 0 ? extraFactories : undefined,
    };
}
